const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) throw new Error('N8N_WEBHOOK_SECRET missing');
const h = $json.headers || {};
const raw = $binary?.data?.data ? Buffer.from($binary.data.data, 'base64').toString('utf8') : JSON.stringify($json.body || {});
const expected = crypto.createHmac('sha256', secret).update(raw, 'utf8').digest('hex');
const supplied = h['x-signature-sha256'] || h['X-Signature-Sha256'];
if (!supplied || supplied !== expected) return [{ json: { authorized: false } }];
const body = $json.body || JSON.parse(raw);
const companyLanes = new Set(['cto','developer','coo','cro','cfo','clo','exec']);
if (!body.action || !['brain_search','checkpoint'].includes(body.action) || typeof body.idempotency_key !== 'string' || !body.request || !companyLanes.has(body.caller_agent) || JSON.stringify(body).toLowerCase().includes('clo-personal')) return [{ json: { authorized: false, reason: 'invalid_action_request' } }];
return [{ json: { authorized: true, body, correlation_id: h['x-correlation-id'], caller_hash: h['x-caller-hash'] } }];
